import {autoMapSpriteRig} from './sprite-rig-retarget.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function openSpriteRigRetarget(editor){
 if(editor.hooks.running())return;
 const guard=await editor.hooks.retargetRevision(),target=structuredClone(editor.doc.data),dialog=editor.element.ownerDocument.createElement('dialog');dialog.className='rig-retarget-dialog';
 dialog.innerHTML='<form method="dialog"><div class="dialog-heading"><h2>2D 클립 리타게팅</h2><button value="cancel" formnovalidate aria-label="닫기">×</button></div><div class="rig-retarget-fields"><label>원본 리그<select data-retarget-source><option value="">선택</option>'+editor.files().filter(f=>f.kind==='spriterig'&&f.path!==editor.doc.path).map(f=>'<option value="'+esc(f.path)+'">'+esc(f.name)+'</option>').join('')+'</select></label><label>원본 클립<select data-retarget-clip></select></label><label>새 클립 이름<input data-retarget-name maxlength="120"></label><label>이동<select data-retarget-mode><option value="boneLength">뼈 길이 비례</option><option value="relative">상대 이동</option><option value="none">이동 제외</option><option value="pose">계층이 다른 리그 포즈 베이크 · IK</option></select></label><button type="button" data-retarget-auto>계층으로 자동 대응</button></div><details><summary>장면 IK 목표</summary><div data-retarget-targets></div></details><div class="rig-retarget-mapping"><table><thead><tr><th>원본 뼈</th><th>대상 뼈</th></tr></thead><tbody></tbody></table></div><p role="status"></p><footer class="dialog-footer"><button value="cancel" formnovalidate>취소</button><button type="button" data-retarget-import disabled>클립 가져오기</button></footer></form>';
 const world=editor.hooks.retargetWorld?.()||{objects:[]};let source,sourceRevision,sourcePath,epoch=0,busy=false;const button=dialog.querySelector('[data-retarget-import]'),message=dialog.querySelector('[role=status]');
 dialog.querySelector('[data-retarget-source]').onchange=async event=>{const current=++epoch;source=null;button.disabled=true;message.textContent='';dialog.querySelector('tbody').innerHTML='';dialog.querySelector('[data-retarget-clip]').innerHTML='';try{const file=await editor.hooks.retargetSource(event.target.value);if(current!==epoch||!dialog.isConnected)return;source=file.editorData||file.data;sourceRevision=file.editorRevision||file.revision;sourcePath=file.path;const mapping=autoMapSpriteRig(source,target);dialog.querySelector('[data-retarget-clip]').innerHTML=source.clips.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('');dialog.querySelector('tbody').innerHTML=source.bones.map(b=>'<tr><td>'+esc(b.name)+'</td><td><select data-retarget-bone="'+esc(b.id)+'" aria-label="'+esc(b.name)+' 대상"><option value="">제외</option>'+target.bones.map(t=>'<option value="'+esc(t.id)+'" '+(mapping.some(m=>m.source===b.id&&m.target===t.id)?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select></td></tr>').join('');const controls=dialog.querySelector('[data-retarget-targets]');controls.innerHTML=[['source',source],['target',target]].flatMap(([side,rig])=>(rig.solvers||[]).map(s=>'<label>'+esc((side==='source'?'원본 · ':'대상 · ')+s.name)+'<select data-retarget-target="'+side+'" data-solver="'+esc(s.id)+'"><option value="">고정 목표</option>'+world.objects.map(o=>'<option value="'+esc(o.id)+'">'+esc(o.name)+'</option>').join('')+'</select></label>')).join('');button.disabled=!source.clips.length;}catch(error){if(current===epoch)message.textContent=error.message;}};
 dialog.querySelector('[data-retarget-auto]').onclick=()=>{if(!source)return;const mapping=autoMapSpriteRig(source,target,{mode:'hierarchy'});for(const select of dialog.querySelectorAll('[data-retarget-bone]'))select.value=mapping.find(m=>m.source===select.dataset.retargetBone)?.target||'';};
 button.onclick=async()=>{if(busy||!source)return;busy=true;button.disabled=true;try{const mapping=[...dialog.querySelectorAll('[data-retarget-bone]')].filter(s=>s.value).map(s=>({source:s.dataset.retargetBone,target:s.value})),name=dialog.querySelector('[data-retarget-name]').value,settings={...guard,source:sourcePath,sourceRevision,clip:dialog.querySelector('[data-retarget-clip]').value,mapping,positionMode:dialog.querySelector('[data-retarget-mode]').value,...name?{name}:{}};if(settings.positionMode==='pose'){const sourceActor=world.objects.find(o=>o.components?.some(c=>c.type==='SpriteSkin'&&c.properties?.rig===sourcePath)),targetActor=world.objects.find(o=>o.components?.some(c=>c.type==='SpriteSkin'&&c.properties?.rig===editor.doc.path)),bindings=[...dialog.querySelectorAll('[data-retarget-target]')].filter(s=>s.value),ids=new Set(bindings.map(s=>s.value));settings.sceneTargets={actors:world.objects.filter(o=>ids.has(o.id)).map(o=>({id:o.id,transform:world.transform?.(o)||{position:o.position,rotation:o.rotation,scale:o.scale}})),sourceTargets:bindings.filter(s=>s.dataset.retargetTarget==='source').map(s=>({solver:s.dataset.solver,actor:s.value})),targetTargets:bindings.filter(s=>s.dataset.retargetTarget==='target').map(s=>({solver:s.dataset.solver,actor:s.value})),sourceTransform:sourceActor?world.transform?.(sourceActor):undefined,targetTransform:targetActor?world.transform?.(targetActor):undefined};}
  // The shared revision/Undo command rejects open modals; retain this form for errors, as with material extraction.
  dialog.close();await editor.hooks.retarget(settings);epoch++;dialog.remove();
 }catch(error){message.textContent=error.message;if(dialog.isConnected&&!editor.disposed)dialog.showModal();else dialog.remove();}finally{busy=false;if(dialog.isConnected)button.disabled=!source?.clips.length;}};
 dialog.addEventListener('close',()=>{if(busy)return;epoch++;dialog.remove();});editor.element.ownerDocument.body.append(dialog);dialog.showModal();dialog.querySelector('[data-retarget-source]').focus();
}
